const http = require('http');

http.createServer((req, res) => {
  if (req.url ==='/') {
    res.write('Hello World');
  } else if(req.url === '/hello') {
    res.write('World');
  }
  res.end();
}).listen(3000);

const express = require('express');

const app = express();
app.get('/', (req, res) => {
  res.send('Hello World');
});

app.get('/hello', (req, res) => {
  res.send('World');
});

app.listen(3000);

